// Little's Law sizing:
// Normal:  400 req/s * 0.05s = 20 concurrent threads
// Brownout: 400 req/s * 2.50s = 1,000 concurrent threads (5x pool size!)

import java.net.http.*;
import java.time.Duration;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicLong;

public class FraudBulkheadClient {
    private final Semaphore bulkhead = new Semaphore(40);
    private final HttpClient http = HttpClient.newBuilder()
            .connectTimeout(Duration.ofMillis(100)).build();
    private final ConcurrentLinkedDeque<Boolean> slowWindow = new ConcurrentLinkedDeque<>();
    private final AtomicLong openUntilNano = new AtomicLong(0);

    public String checkFraud(HttpRequest req) throws Exception {
        if (System.nanoTime() < openUntilNano.get()) {
            throw new RejectedExecutionException("Fraud circuit OPEN");
        }
        if (!bulkhead.tryAcquire()) {
            throw new RejectedExecutionException("Fraud bulkhead FULL (40/40)");
        }
        long start = System.nanoTime();
        boolean slowOrFailed = false;
        try {
            HttpRequest timed = HttpRequest.newBuilder(req, (k, v) -> true)
                    .timeout(Duration.ofMillis(250)).build();
            HttpResponse<String> res = http.send(timed, HttpResponse.BodyHandlers.ofString());
            if (System.nanoTime() - start > 200_000_000L || res.statusCode() >= 500) {
                slowOrFailed = true;
            }
            return res.body();
        } catch (Exception e) {
            slowOrFailed = true;
            throw e;
        } finally {
            bulkhead.release();
            recordOutcome(slowOrFailed);
        }
    }

    private synchronized void recordOutcome(boolean slowOrFailed) {
        slowWindow.addLast(slowOrFailed);
        if (slowWindow.size() > 50) slowWindow.removeFirst();
        if (slowWindow.size() == 50 && slowWindow.stream().filter(b -> b).count() >= 25) {
            openUntilNano.set(System.nanoTime() + 10_000_000_000L); // Open 10s
            slowWindow.clear();
        }
    }
}

// Even on Virtual Threads, protect downstream & memory with a Semaphore bulkhead
try (var ignored = acquirePermit(bulkhead)) {
    return callFraudApi();
}
